#!/usr/bin/env node
// Generate docs/schema.md and the ER diagram in README.md from the database
// catalog, so the documentation cannot drift from the migrations.
//
//   npm run docs            rewrite the generated files
//   npm run docs -- --check exit 1 if they are out of date (used by CI)

import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate, openDatabase } from '../src/database.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SCHEMA_DOC = path.join(ROOT, 'docs', 'schema.md');
const README = path.join(ROOT, 'README.md');
const README_START = '<!-- er-diagram:start (generated by npm run docs) -->';
const README_END = '<!-- er-diagram:end -->';

/** Read everything the docs need from the catalog. */
export async function readCatalog(db) {
  const tables = (
    await db.query(`
      select c.relname as name, c.relkind as kind, obj_description(c.oid, 'pg_class') as comment
      from pg_class as c join pg_namespace as n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind in ('r', 'v') and c.relname <> 'schema_migrations'
      order by c.relkind, c.oid`)
  ).rows;

  const columns = (
    await db.query(`
      select c.relname as table_name, a.attname as name, format_type(a.atttypid, a.atttypmod) as type,
             a.attnotnull as not_null, pg_get_expr(d.adbin, d.adrelid) as default_value,
             a.attgenerated <> '' as generated, a.attidentity <> '' as identity,
             col_description(c.oid, a.attnum) as comment
      from pg_attribute as a
      join pg_class as c on c.oid = a.attrelid
      join pg_namespace as n on n.oid = c.relnamespace
      left join pg_attrdef as d on d.adrelid = a.attrelid and d.adnum = a.attnum
      where n.nspname = 'public' and c.relkind in ('r', 'v') and a.attnum > 0 and not a.attisdropped
      order by c.oid, a.attnum`)
  ).rows;

  const constraints = (
    await db.query(`
      select con.conrelid::regclass::text as table_name, con.conname as name, con.contype as type,
             pg_get_constraintdef(con.oid) as definition, con.confrelid::regclass::text as references_table,
             array(select a.attname from unnest(con.conkey) with ordinality as k(attnum, ord)
                   join pg_attribute as a on a.attrelid = con.conrelid and a.attnum = k.attnum
                   order by k.ord)::text[] as columns
      from pg_constraint as con join pg_namespace as n on n.oid = con.connamespace
      where n.nspname = 'public'
      order by con.conrelid, con.contype, con.conname`)
  ).rows;

  return { tables, columns, constraints };
}

const shortType = (type) =>
  type
    .replace(/\(.*\)/, '')
    .replace('character varying', 'varchar')
    .replace('character', 'char')
    .replace('integer', 'int')
    .replace(/ /g, '_');

function relationships({ columns, constraints }) {
  const isNotNull = (table, cols) =>
    cols.every((c) => columns.find((x) => x.table_name === table && x.name === c)?.not_null);
  const isUnique = (table, cols) =>
    constraints.some(
      (k) => k.table_name === table && (k.type === 'p' || k.type === 'u') && k.columns.join() === cols.join(),
    );
  return constraints
    .filter((k) => k.type === 'f')
    .map((k) => ({
      parent: k.references_table,
      child: k.table_name,
      parentCard: isNotNull(k.table_name, k.columns) ? '||' : '|o',
      childCard: isUnique(k.table_name, k.columns) ? 'o|' : 'o{',
      label: k.columns.join(', '),
    }));
}

/** Tables that only hold a multivalued attribute (phones, emails, ...), per their comment. */
const isAttributeTable = (catalog, name) =>
  /\(multivalued( composite)? attribute\)/.test(catalog.tables.find((t) => t.name === name)?.comment ?? '');

/**
 * Mermaid erDiagram. `attributes` lists every column with PK/FK markers;
 * `core` leaves out the multivalued-attribute tables to keep it readable.
 */
export function erDiagram(catalog, { attributes = false, core = false } = {}) {
  const lines = ['erDiagram'];
  const included = (name) => !core || !isAttributeTable(catalog, name);
  for (const r of relationships(catalog).filter((r) => included(r.child))) {
    lines.push(`    ${r.parent} ${r.parentCard}--${r.childCard} ${r.child} : "${r.label}"`);
  }
  if (attributes) {
    for (const table of catalog.tables.filter((t) => t.kind === 'r')) {
      const keys = catalog.constraints.filter((k) => k.table_name === table.name);
      const pk = new Set(keys.filter((k) => k.type === 'p').flatMap((k) => k.columns));
      const fk = new Set(keys.filter((k) => k.type === 'f').flatMap((k) => k.columns));
      lines.push(`    ${table.name} {`);
      for (const col of catalog.columns.filter((c) => c.table_name === table.name)) {
        const marks = [pk.has(col.name) && 'PK', fk.has(col.name) && 'FK'].filter(Boolean).join(', ');
        lines.push(`        ${shortType(col.type)} ${col.name}${marks ? ` ${marks}` : ''}`);
      }
      lines.push('    }');
    }
  }
  return lines.join('\n');
}

const escapeCell = (text) => (text ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ');

function splitOriginal(comment) {
  const match = /^(.*?)\s*(?:Original: (.+?)\.?|(New)\.?)$/.exec(comment ?? '');
  if (!match) return { description: comment ?? '', original: '' };
  return { description: match[1], original: match[2] ?? 'new' };
}

/** Make pg_get_constraintdef output readable: drop casts, turn = ANY (ARRAY[...]) into IN (...). */
export function readableCheck(definition) {
  let text = definition
    .replace(/^CHECK /, '')
    .replace(/::(?:character varying|text|numeric|integer|smallint)(?:\[\])?/g, '')
    .replace(/= ANY \(\(?ARRAY\[(.*?)\]\)?\)/g, 'IN ($1)');
  // Strip parentheses that wrap the whole expression or a bare value.
  for (let previous = ''; previous !== text; ) {
    previous = text;
    text = text.replace(/\((\w+|'[^']*'|\([^()]*\))\)/g, '$1');
    if (/^\(.*\)$/.test(text) && balanced(text.slice(1, -1))) text = text.slice(1, -1);
  }
  return text;
}

function balanced(text) {
  let depth = 0;
  for (const ch of text) {
    depth += ch === '(' ? 1 : ch === ')' ? -1 : 0;
    if (depth < 0) return false;
  }
  return depth === 0;
}

function constraintSummary(k) {
  if (k.type === 'f') {
    const target = /REFERENCES (\S+?)\(([^)]*)\)\s*(.*)$/i.exec(k.definition);
    const actions = (target?.[3] ?? '').toLowerCase();
    return `\`${k.columns.join(', ')}\` → \`${target?.[1]}.${target?.[2]}\`${actions ? `, ${actions}` : ''}`;
  }
  if (k.type === 'c') return `check \`${readableCheck(k.definition)}\``;
  if (k.type === 'u') {
    return `unique (\`${k.columns.join(', ')}\`)${k.definition.includes('NULLS NOT DISTINCT') ? ', nulls not distinct' : ''}`;
  }
  return null;
}

export function schemaMarkdown(catalog) {
  const out = [
    '# Schema reference',
    '',
    '<!-- Generated by `npm run docs` from the database catalog. Do not edit by hand:',
    '     change the migrations (table and column comments live in',
    '     db/migrations/20261014000003_document_schema.sql) and regenerate. -->',
    '',
    'PostgreSQL 18. Every table, column and view below is documented in the database itself',
    '(`\\d+ table_name` in psql shows the same text). The **Original** column names the',
    'corresponding table or column in the 2022 Oracle design; see [errata.md](errata.md) for',
    'what changed and why, and [design-decisions.md](design-decisions.md) for the reasoning.',
    '',
    '## Entity-relationship diagram',
    '',
    '`||` exactly one, `|o` zero or one, `o{` zero or many. Labels are the foreign-key columns.',
    '',
    '```mermaid',
    erDiagram(catalog, { attributes: true }),
    '```',
    '',
    '## Tables',
    '',
  ];

  for (const table of catalog.tables.filter((t) => t.kind === 'r')) {
    const { description, original } = splitOriginal(table.comment);
    const keys = catalog.constraints.filter((k) => k.table_name === table.name);
    const pk = keys.find((k) => k.type === 'p');
    const fkCols = new Set(keys.filter((k) => k.type === 'f').flatMap((k) => k.columns));
    out.push(`### \`${table.name}\``, '', description, '');
    if (original) out.push(`Original: ${original}`, '');
    out.push('| Column | Type | Null | Key | Description | Original |', '|---|---|---|---|---|---|');
    for (const col of catalog.columns.filter((c) => c.table_name === table.name)) {
      const key = [pk?.columns.includes(col.name) && 'PK', fkCols.has(col.name) && 'FK'].filter(Boolean).join(', ');
      const extra = col.generated
        ? ` Generated: \`${col.default_value}\`.`
        : col.identity
          ? ' Identity.'
          : col.default_value
            ? ` Default \`${col.default_value}\`.`
            : '';
      const c = splitOriginal(col.comment);
      out.push(
        `| \`${col.name}\` | ${col.type} | ${col.not_null ? 'no' : 'yes'} | ${key} | ${escapeCell(c.description + extra)} | ${escapeCell(c.original)} |`,
      );
    }
    const rules = keys.map(constraintSummary).filter(Boolean);
    if (rules.length) {
      out.push('', 'Constraints:', '', ...rules.map((r) => `- ${escapeCell(r)}`));
    }
    out.push('');
  }

  out.push('## Views', '');
  for (const view of catalog.tables.filter((t) => t.kind === 'v')) {
    const cols = catalog.columns.filter((c) => c.table_name === view.name).map((c) => `\`${c.name}\``);
    out.push(`### \`${view.name}\``, '', view.comment ?? '', '', `Columns: ${cols.join(', ')}`, '');
  }
  return `${out.join('\n').trimEnd()}\n`;
}

export function readmeWithDiagram(readme, catalog) {
  const start = readme.indexOf(README_START);
  const end = readme.indexOf(README_END);
  if (start < 0 || end < start) throw new Error('README.md is missing the er-diagram markers');
  const block = `${README_START}\n\n\`\`\`mermaid\n${erDiagram(catalog, { core: true })}\n\`\`\`\n\n`;
  return readme.slice(0, start) + block + readme.slice(end);
}

/** The generated files and their expected contents. */
export async function generatedFiles() {
  const db = await openDatabase({ url: '' });
  try {
    await migrate(db);
    const catalog = await readCatalog(db);
    return [
      [SCHEMA_DOC, schemaMarkdown(catalog)],
      [README, readmeWithDiagram(await readFile(README, 'utf8'), catalog)],
    ];
  } finally {
    await db.close();
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const [file, content] of await generatedFiles()) {
    const current = await readFile(file, 'utf8').catch(() => '');
    if (current === content) continue;
    stale++;
    if (check) console.error(`${path.relative(ROOT, file)} is out of date. Run "npm run docs".`);
    else await writeFile(file, content);
  }
  if (check && stale) process.exit(1);
  console.log(check ? 'Generated docs are up to date.' : `Updated ${stale} file(s).`);
}
